window.AUTH=window.AUTH||{};window.AUTH["21-1450"]={"d":"21-1450","id":"2022/21-1450","n":"Turkiye Halk Bankasi A.S. v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Turkiye Halk Bankasi A.S.","date":"2022-11-14","url":"https://www.supremecourt.gov/DocketPDF/21/21-1450/246391/20221114142235857_Halkbank%20Brief%20for%20Petitioner%20and%20Statutory%20Addendum.pdf","side":"pet","n":64},{"k":"respondent","label":"Brief of respondent United States","date":"2022-12-14","url":"https://www.supremecourt.gov/DocketPDF/21/21-1450/249958/20221214150140875_21-1450bsUnitedStates.pdf","side":"res","n":85},{"k":"reply","label":"Reply of petitioner Turkiye Halk Bankasi A.S.","date":"2023-01-06","url":"https://www.supremecourt.gov/DocketPDF/21/21-1450/251530/20230106112315272_Halkbank%20Reply%20Brief.pdf","side":"pet","n":46}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us1r13_3e04.pdf","tr":true,"items":[{"t":"case","label":"Abney v. United States","cite":"431 U.S. 651","y":1977,"id":"1976/75-6521","sc":1,"sum":"Petitioners and others were charged in a single-count indictment with conspiracy and an attempt to obstruct interstate commerce by means of extortion, in violation of the Hobbs Act. Petitioners challenged the indictment as duplicitous, contending that its single count improperly charged both a conspiracy and an attempt to violate the Hobbs Act. The District Court refused to dismiss the indictment but required the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Alfred Dunhill of London, Inc. v. Republic of Cuba","cite":"425 U.S. 682","y":1976,"id":"1974/73-1288","sc":1,"sum":"The Supreme Court held that the record contained no evidence to support an act of state. There was no statute, decree or order by the Cuban Government refusing to pay, only a statement by the interventor’s counsel during trial. The interventors did not possess governmental power just because the Cuban government appointed them. The affirmative judgment for the one purchaser was restored.","sumSrc":"Oyez","by":{"0":"44","1":"21, 29","2":"16"}},{"t":"case","label":"Argentine Republic v. Amerada Hess Shipping Corp.","cite":"488 U.S. 428","y":1989,"id":"1988/87-1372","sc":1,"op":4,"sum":"The FSIA provides the sole basis for obtaining jurisdiction over a foreign state in United States courts, and the District Court correctly dismissed the action because the FSIA did not authorize jurisdiction over petitioner under the facts of this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"36, 40","2":"6, 10, 18"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26"}},{"t":"case","label":"Badgerow v. Walters","cite":"142 S. Ct. 1310","y":2022,"id":"2021/20-1143","sc":1,"sum":"Federal jurisdiction in a petition to compel arbitration under Section 4 of the Federal Arbitration Act is determined by “looking through” the petition to the jurisdictional basis of the “underlying substantive controversy,” Vaden v. Discover Bank, 556 U. S. 49, 62, but that approach does not apply to petitions to confirm or vacate arbitral awards under Sections 9 and 10 of the FAA.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14, 40"}},{"t":"case","label":"Benz v. Compania Naviera Hidalgo, S.A.","cite":"353 U.S. 138","y":1957,"id":"1956/204","sc":1,"sum":"The Labor Management Relations Act of 1947 does not apply to a controversy involving damages resulting from the picketing of a foreign ship operated entirely by foreign seamen under foreign articles while the vessel is temporarily in an American port, though American unions to which the foreign seamen did not belong participated in the picketing; and the Act therefore does not preclude a remedy under state law for …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Berizzi Bros. v. S.S. Pesaro","cite":"271 U.S. 562","y":1926,"id":"scdb/1925-172","sc":1,"ar":1,"sum":"A ship owned and possessed by a friendly foreign government, and operated by it in the carriage of merchandise for hire, in the interest and service of the nation, is a public ship and is immune from arrest under process based on a libel in rem by a private suitor; and the District Court has no jurisdiction of the case under Jud. Code, § 24, cl. 3, granting that court jurisdiction of \"all civil causes of admirality …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"20","2":"4-5, 16"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne Int’l Drilling Co.","cite":"137 S. Ct. 1312","y":2017,"id":"2016/15-423","sc":1,"sum":"The Court determined that the “frivolous or insubstantial” standard is not consistent with the text and purpose of the Foreign Sovereign Immunities Act (FSIA)","sumSrc":"Oyez","by":{"0":"13, 15, 31","2":"4"}},{"t":"case","label":"Breard v. Greene","cite":"523 U.S. 371","y":1998,"id":"1997/97-8214","sc":1,"sum":"The majority of the Court concluded that, because he had procedurally defaulted it, Breard could not raise his Vienna Convention claim on federal habeas corpus review. Moreover, the Court reasoned that Breard could not have demonstrated that the alleged violation of the Vienna Convention had an effect on his state trial that ought to have resulted in the overturning of his conviction.","sumSrc":"Oyez","by":{"0":"23","2":"5"}},{"t":"case","label":"Compania Espanola de Navegacion Maritima, S.A. v. The Navemar","cite":"303 U.S. 68","y":1938,"id":"scdb/1937-121","sc":1,"sum":"(1) That the Ambassador's application was properly entertained. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"EEOC v. Arabian Am. Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"sum":"Title VII does not apply extraterritorially to regulate the employment practices of United States firms that employ American citizens abroad. Petitioners' evidence, while not totally lacking in probative value, falls short of demonstrating the clearly expressed affirmative congressional intent that is required to overcome the well-established presumption against statutory extraterritoriality.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 27"}},{"t":"case","label":"F. Hoffman-La Roche Ltd. v. Empagran S.A.","cite":"542 U.S. 155","y":2004,"id":"2003/03-724","sc":1,"op":1,"sum":"The Court unanimously ruled that Congress' intent in passing the FTAIA was to prevent American courts from interfering in foreign commerce. Congress made an exception for foreign commerce that affected domestic commerce, but the exception should not be read as a general prohibition against price-fixing in all parts of the world.","sumSrc":"Oyez","by":{"0":"21, 22"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"ar":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"23, 39"}},{"t":"case","label":"First Nat’l City Bank v. Banco Nacional de Cuba","cite":"406 U.S. 759","y":1972,"id":"1971/70-295","sc":1,"sum":"The judgment is reversed. Pp. 762-776. MR. JUSTICE REHNQUIST, joined by THE CHIEF JUSTICE and MR. JusTIcE WHITE, concluded that since the Executive Branch, which is charged with the primary responsibility for the conduct of foreign affairs, has (contrary to the position it took in Sabbatino) expressly represented to the Court that the application of the act of state doctrine in this case would not advance the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17","1":"10"}},{"t":"case","label":"Fourco Glass Co. v. Transmirra Prods. Corp.","cite":"353 U.S. 222","y":1957,"id":"1956/310","sc":1,"sum":"1. Venue in patent infringement actions is governed exclusively by 28 U. S. C. § 1400 (b), which provides that any such action may be brought \"in the judicial district where the defendant resides, or where the defendant has committed acts of infringement and has a regular and established place of business\"; and 28 U. S. C. § 1391 (c) has no application to such actions. Stonite Products Co. v. Melvin Lloyd Co., 315 …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Franchise Tax Bd. v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"sum":"Nevada v. Hall, 440 U. S. 410, is overruled; States retain their sovereign immunity from private suits brought in courts of other States.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"15"}},{"t":"case","label":"Helstoski v. Meanor","cite":"442 U.S. 500","y":1979,"id":"1978/78-546","sc":1,"sum":"Mandamus was not the appropriate means of challenging the validity of the indictment on the ground that it violated the Speech or Debate Clause. Direct appeal to the Court of Appeals was available and was the proper course.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Jam v. Int’l Fin. Corp.","cite":"139 S. Ct. 759","y":2019,"id":"2018/17-1011","sc":1,"sum":"The International Organizations Immunities Act of 1945 affords international organizations the same immunity from suit that foreign governments enjoy today under the Foreign Sovereign Immunities Act of 1976.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35","1":"39"}},{"t":"case","label":"Kiobel v. Royal Dutch Petrol.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"sum":"The Court found that the Alien Tort Statute does not give ground for United States law to be applied extraterrestrially to other sovereign nations with their own laws.","sumSrc":"Oyez","by":{"0":"16, 20","1":"30"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Lane v. Peña","cite":"518 U.S. 187","y":1996,"id":"1995/95-365","sc":1,"sum":"Although the related provisions of the 1973 Rehabilitation Act and the 1991 Civil Rights Act might in combination be read as waiving the federal government's sovereign immunity, absent an unambiguous waiver of sovereign immunity, the court cannot permit damages to be awarded.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"McCulloch v. Sociedad Nacional de Marineros de Honduras","cite":"372 U.S. 10","y":1963,"id":"1962/107","sc":1,"sum":"The jurisdictional provisions of the National Labor Relations Act do not extend to the maritime operations of such foreign-flag ships employing alien seamen.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 31"}},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"sum":"The Court held that, for the purpose of federal bribery statutes, an “official act” is a decision or action on a question, matter, cause, suit, proceeding, or controversy that involves a specific exercise of formal governmental power.","sumSrc":"Oyez","by":{"0":"32, 43"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"sum":"In 1970, petitioner, who was then the Attorney General, authorized a warrantless wiretap for the purpose of gathering intelligence regarding the activities of a radical group that had made tentative plans to take actions threatening the Nation's security. During the time the wiretap was installed, the Government intercepted three conversations between a member of the group and respondent. Thereafter, this Court in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Murray v. Schooner Charming Betsy","cite":"6 U.S. 64","y":1804,"id":"scdb/1804-007","sc":1,"by":{"0":"10, 18, 43"}},{"t":"case","label":"N.Y. Cent. R.R. Co. v. Chisholm","cite":"268 U.S. 29","y":1925,"id":"scdb/1924-118","sc":1,"sum":"1. The -right of action given by the Employers’ Liability Act is based wholly on tort.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Nat’l City Bank of N.Y. v. Republic of China","cite":"348 U.S. 356","y":1955,"id":"scdb/1954-035","sc":1,"sum":"The counterclaims should not have been dismissed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 30"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"0":"45, 46","1":"44, 46","2":"22"}},{"t":"case","label":"Odhiambo v. Republic of Kenya","cite":"764 F.3d 31","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/764/31/","by":{"0":"46, 47","2":"24"}},{"t":"case","label":"Opati v. Republic of Sudan","cite":"140 S. Ct. 1601","y":2020,"id":"2019/17-1268","sc":1,"op":1,"sum":"The Court held that the Foreign Sovereign Immunities Act (FSIA) applies retroactively, thereby permitting recovery of punitive damages against foreign states for terrorist activities occurring prior to the passage of the current version of the statute.","sumSrc":"Oyez","by":{"0":"33","1":"21"}},{"t":"case","label":"Permanent Mission of India to the U.N. v. City of New York","cite":"551 U.S. 193","y":2007,"id":"2006/06-134","sc":1,"sum":"The Court held 7-2 that the \"immovable property\" exception to sovereign immunity in the FSIA covers disputes over tax liens on the property as well as disputes over ownership and possession. The opinion by Justice Clarence Thomas ruled that a tax lien, by both its dictionary definition and its practical effect, is an interest or right in property.","sumSrc":"Oyez","by":{"0":"34","2":"20"}},{"t":"case","label":"Persinger v. Islamic Republic of Iran","cite":"729 F.2d 835","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/729/835/","by":{"0":"31"}},{"t":"case","label":"Republic of Argentina v. NML Cap., Ltd.","cite":"573 U.S. 134","y":2014,"id":"2013/12-842","sc":1,"op":2,"sum":"The Court held that, under the Foreign Sovereign Immunities Act, property held within the US by foreign nations cannot be attached to civil claims unless certain exceptions are met.","sumSrc":"Oyez","by":{"0":"35","1":"33"}},{"t":"case","label":"Republic of Argentina v. Weltover, Inc.","cite":"504 U.S. 607","y":1992,"id":"1991/91-763","sc":1,"sum":"The Court held that the District Court properly asserted jurisdiction under the FSIA.","sumSrc":"Oyez","by":{"0":"46, 47","1":"47","2":"24"}},{"t":"case","label":"Republic of Austria v. Altmann","cite":"541 U.S. 677","y":2004,"id":"2003/03-13","sc":1,"op":3,"sum":"In a 6-to-3 decision written by Justice John Paul Stevens, the Court ruled that, while the Foreign Sovereign Immunities Act of 1976 does not explicitly state that it should be applied to actions that took place before its passage, there are strong indications in the text of the statute that Congress intended it to apply retroactively.","sumSrc":"Oyez","by":{"0":"28, 34, 35","2":"18"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"139 S. Ct. 1048","y":2019,"id":"2018/16-1094","sc":1,"sum":"When civil process is served on a foreign state under the Foreign Sovereign Immunities Act of 1976, 28 U. S. C. §1608(a)(3) requires a mailing to be sent directly to the foreign minister’s office in the foreign state.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"38","2":"10"}},{"t":"case","label":"Return Mail, Inc. v. USPS","cite":"139 S. Ct. 1853","y":2019,"id":"2018/17-1594","sc":1,"sum":"The Federal Government is not a “person” capable of petitioning the Patent Trial and Appeal Board to institute patent review proceedings under the Leahy-Smith America Invents Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23"}},{"t":"case","label":"RJR Nabisco, Inc. v. Eur. Cmty.","cite":"579 U.S. 325","y":2016,"id":"2015/15-138","sc":1,"sum":"The Court held that some sections of the Racketeer Influenced Corrupt Organizations (RICO) statute can apply extraterritorially because Congress clearly based them on predicate offenses that can occur outside of the United States.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"138 S. Ct. 816","y":2018,"id":"2017/16-534","sc":1,"op":2,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"0":"40","1":"21"}},{"t":"case","label":"Samantar v. Yousuf","cite":"560 U.S. 305","y":2010,"id":"2009/08-1555","sc":1,"op":9,"ar":6,"sum":"The Court held that the Foreign Sovereign Immunities Act does not extend to an individual acting in his official capacity on behalf of the foreign state.","sumSrc":"Oyez","by":{"0":"35, 44","1":"passim","2":"5, 19"}},{"t":"case","label":"Saudi Arabia v. Nelson","cite":"507 U.S. 349","y":1993,"id":"1992/91-522","sc":1,"ar":1,"sum":"The Nelsons' action is not \"based upon a commercial activity\" within the meaning of the first clause of § 1605(a)(2), and the Act therefore confers no jurisdiction over their suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47, 48"}},{"t":"case","label":"Schooner Exchange v. McFaddon","cite":"11 U.S. 116","y":1812,"id":"scdb/1812-014","sc":1,"sum":"Present...dllljke judges.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"passim","2":"2, 4-5, 8-9, 12, 16-17"}},{"t":"case","label":"Sell v. United States","cite":"539 U.S. 166","y":2003,"id":"2002/02-5664","sc":1,"sum":"The Court held that the Constitution allows the Federal Government to administer antipsychotic drugs, even against the defendant's will, in limited circumstances.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"United States v. Atilla","cite":"966 F.3d 118","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/966/118/","by":{"0":"8","1":"4"}},{"t":"case","label":"United States v. Halkbank","cite":"2020 WL 5849512","y":2020,"court":"S.D.N.Y.","op":69,"ar":2,"by":{"0":"1"}},{"t":"case","label":"United States v. Jasin","cite":"1993 WL 259436","y":1993,"court":"E.D. Pa. July 7","by":{"0":"30","1":"25"}},{"t":"case","label":"United States v. Palmer","cite":"16 U.S. 610","y":1818,"id":"scdb/1818-038","sc":1,"sum":"A robbcry committed on the high seas, although such robbery if com., milled on land would not by the lav s of the United Surtes bo punishable with death, is piracy under the 8th section of the act of 1700 ch. 36, (ix) for the punishment of certain crimes against the United Slates; and the circuit court have jurisdiction thereof.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"United States v. Türkiye Halk Bankasi A.Ş.","cite":"16 F.4th 336","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/16/336/","op":4,"by":{"0":"1"}},{"t":"case","label":"Verlinden B.V. v. Cent. Bank of Nigeria","cite":"461 U.S. 480","y":1983,"id":"1982/81-920","sc":1,"op":5,"sum":"The Supreme Court held that the FSIA does not violate Article III. The FSIA was a valid exercise of Congress’ power to regulate foreign commerce. On remand, the court of appeals should consider whether Central Bank is entitled to sovereign immunity.","sumSrc":"Oyez","by":{"0":"15, 33, 35"}},{"t":"case","label":"West Virginia v. EPA","cite":"142 S. Ct. 2587","y":2022,"id":"2021/20-1530","sc":1,"sum":"Congress did not grant the Environmental Protection Agency in Section 111(d) of the Clean Air Act the authority to devise emissions caps based on the generation shifting approach the Agency took in the Clean Power Plan.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"23"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(27)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§101. Definitions","tname":"Bankruptcy","by":{"0":"28","1":"13"}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","by":{"0":"39"}},{"t":"usc","label":"22 U.S.C. § 8513a","url":"https://www.law.cornell.edu/uscode/text/22/8513a","subs":["(d)(2)","(d)(4)(C)"],"stext":{"head":"§8513a. Imposition of sanctions with respect to the financial sector of Iran","paras":[[0,"(a) Findings"],[0,"Congress makes the following findings:"],[1,"(1) On November 21, 2011, the Secretary of the Treasury issued a finding under section 5318A of title 31 that identified Iran as a jurisdiction of primary money laundering concern."],[1,"(2) In that finding, the Financial Crimes Enforcement Network of the Department of the Treasury wrote, \"The Central Bank of Iran, which regulates Iranian banks, has assisted designated Iranian banks by transferring billions of dollars to these banks in 2011. In mid-2011, the CBI transferred several billion dollars to designated banks, including Saderat, Mellat, EDBI and Melli, through a variety of payment schemes. In making these transfers, the CBI attempted to evade sanctions by minimizing the direct involvement of large international banks with both CBI and designated Iranian banks.\"."],[1,"(3) On November 22, 2011, the Under Secretary of the Treasury for Terrorism and Financial Intelligence, David Cohen, wrote, \"Treasury is calling out the entire Iranian banking sector, including the Central Bank of Iran, as posing terrorist financing, proliferation financing, and money laundering risks for the global financial system.\"."],[0,"(b) Designation of financial sector of Iran as of primary money laundering concern"],[0,"The financial sector of Iran, including the Central Bank of Iran, is designated as a primary money laundering concern for purposes of section 5318A of title 31 because of the threat to government and financial institutions resulting from the illicit activities of the Government of Iran, including its pursuit of nuclear weapons, support for international terrorism, and efforts to deceive responsible financial institutions and evade sanctions."],[0,"(c) Freezing of assets of Iranian financial institutions"],[0,"The President shall, pursuant to the International Emergency Economic Powers Act (50 U.S.C. 1701 et seq.), block and prohibit all transactions in all property and interests in property of an Iranian financial institution if such property and interests in property are in the United States, come within the United States, or are or come within the possession or control of a United States person."],[0,"(d) Imposition of sanctions with respect to the Central Bank of Iran and other Iranian financial institutions"],[0,"(1) In general"],[1,"Except as specifically provided in this subsection, beginning on the date that is 60 days after December 31, 2011, the President—"],[2,"(A) shall prohibit the opening, and prohibit or impose strict conditions on the maintaining, in the United States of a correspondent account or a payable-through account by a foreign financial institution that the President determines has knowingly conducted or facilitated any significant financial transaction with the Central Bank of Iran or another Iranian financial institution designated by the Secretary of the Treasury for the imposition of sanctions pursuant to the International Emergency Economic Powers Act (50 U.S.C. 1701 et seq.); and"],[2,"(B) may impose sanctions pursuant to the International Emergency Economic Powers Act (50 U.S.C. 1701 et seq.) with respect to the Central Bank of Iran."],[0,"(2) Exception for sales of agricultural commodities, food, medicine, and medical devices"],[1,"The President may not impose sanctions under paragraph (1) with respect to any person for conducting or facilitating a transaction for the sale of agricultural commodities, food, medicine, or medical devices to Iran."],[0,"(3) Applicability of sanctions with respect to foreign central banks"],[1,"Except as provided in paragraph (4), sanctions imposed under paragraph (1)(A) shall apply with respect to a central bank of a foreign country, only insofar as it engages in a financial transaction for the sale or purchase of petroleum or petroleum products to or from Iran conducted or facilitated on or after that date that is 180 days after December 31, 2011."],[0,"(4) Applicability of sanctions with respect to petroleum transactions"],[0,"(A) Report required"],[2,"Not later than October 25, 2012, and the last Thursday of every other month thereafter, the Administrator of the Energy Information Administration, in consultation with the Secretary of the Treasury, the Secretary of State, and the Director of National Intelligence, shall submit to Congress a report on the availability and price of petroleum and petroleum products produced in countries other than Iran in the 2-month period preceding the submission of the report."],[0,"(B) Determination required"],[2,"Not later than 90 days after December 31, 2011, and every 180 days thereafter, the President shall make a determination, based on the reports required by subparagraph (A), of whether the price and supply of petroleum and petroleum products produced in countries other than Iran is sufficient to permit purchasers of petroleum and petroleum products from Iran to reduce significantly in volume their purchases from Iran."],[0,"(C) Application of sanctions"],[2,"Except as provided in subparagraph (D), sanctions imposed under paragraph (1)(A) shall apply with respect to a financial transaction conducted or facilitated by a foreign financial institution on or after the date that is 180 days after December 31, 2011, for the purchase of petroleum or petroleum products from Iran if the President determines pursuant to subparagraph (B) that there is a sufficient supply of petroleum and petroleum products from countries other than Iran to permit a significant reduction in the volume of petroleum and petroleum products purchased from Iran by or through foreign financial institutions."],[0,"(D) Exception"],[0,"(i) In general"],[3,"Sanctions imposed pursuant to paragraph (1) shall not apply with respect to a financial transaction described in clause (ii) conducted or facilitated by a foreign financial institution if the President determines and reports to Congress, not later than 90 days after the date on which the President makes the determination required by subparagraph (B), and every 180 days thereafter, that the country with primary jurisdiction over the foreign financial institution—"],[4,"(I) has significantly reduced reduced 1 its volume of crude oil purchases from Iran during the period beginning on the date on which the President submitted the last report with respect to the country under this subparagraph; or"],[4,"(II) in the case of a country that has previously received an exception under this subparagraph, has, after receiving the exception, reduced its crude oil purchases from Iran to zero."],[0,"(ii) Financial transactions described"],[3,"A financial transaction conducted or facilitated by a foreign financial institution is described in this clause if—"],[4,"(I) the financial transaction is only for trade in goods or services between the country with primary jurisdiction over the foreign financial institution and Iran; and"],[4,"(II) any funds owed to Iran as a result of such trade are credited to an account located in the country with primary jurisdiction over the foreign financial institution."],[0,"(5) Applicability of sanctions with respect to Chinese financial institutions"],[0,"(A) In general"],[2,"For the purpose of paragraph (1)(A), a \"significant financial transaction\" shall include, based on relevant facts and circumstances, any transaction—"],[3,"(i) by a Chinese financial institution (without regard to the size, number, frequency, or nature of the transaction) involving the purchase of petroleum or petroleum products from Iran; and"],[3,"(ii) by a foreign financial institution (without regard to the size, number, frequency, or nature of the transaction) involving the purchase of Iranian unmanned aerial vehicles (UAVs), UAV parts, or related systems."],[0,"(B) Determination required"],[2,"Not later than 180 days after April 24, 2024, and every year thereafter for 5 years, the President shall—"],[3,"(i) determine whether any—"],[4,"(I) Chinese financial institution has engaged in a significant financial transaction as described in paragraph (1)(A)(i); and"],[4,"(II) financial institution has engaged in a significant financial transaction as described in paragraph (1)(A)(ii); and"],[3,"(ii) transmit the determination under clause (i) to the Committee on Foreign Affairs and the Committee on Financial Services of the House of Representatives and to the Committee on Foreign Relations and the Committee on Banking, Housing, and Urban Affairs of the Senate."],[0,"(6) Waiver"],[1,"The President may waive the imposition of sanctions under paragraph (1) for a period of not more than 120 days, and may renew that waiver for additional periods of not more than 120 days, if the President—"],[2,"(A) determines that such a waiver is in the national security interest of the United States; and"],[2,"(B) submits to Congress a report—"],[3,"(i) providing a justification for the waiver;"],[3,"(ii) certifying that the country with primary jurisdiction over the foreign financial institution otherwise subject to the sanctions faced exceptional circumstances that prevented the country from being able to reduce significantly its purchases of petroleum and petroleum products from Iran; and"],[3,"(iii) that includes any concrete cooperation the President has received or expects to receive as a result of the waiver."],[0,"(e) Multilateral diplomacy initiative"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/8513a?type=usc&year=mostrecent&link-type=html"},"head":"§8513a. Imposition of sanctions with respect to the financial sector of Iran","tname":"Foreign Relations and Intercourse","by":{"0":"42","1":"3, 3"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1605","url":"https://www.law.cornell.edu/uscode/text/28/1605","subs":["(a)","(a)(2)","(a)(5)","(a)(6)","(g)"],"stext":{"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","paras":[[0,"(a) A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case—"],[1,"(1) in which the foreign state has waived its immunity either explicitly or by implication, notwithstanding any withdrawal of the waiver which the foreign state may purport to effect except in accordance with the terms of the waiver;"],[1,"(2) in which the action is based upon a commercial activity carried on in the United States by the foreign state; or upon an act performed in the United States in connection with a commercial activity of the foreign state elsewhere; or upon an act outside the territory of the United States in connection with a commercial activity of the foreign state elsewhere and that act causes a direct effect in the United States;"],[1,"(3) in which rights in property taken in violation of international law are in issue and that property or any property exchanged for such property is present in the United States in connection with a commercial activity carried on in the United States by the foreign state; or that property or any property exchanged for such property is owned or operated by an agency or instrumentality of the foreign state and that agency or instrumentality is engaged in a commercial activity in the United States;"],[1,"(4) in which rights in property in the United States acquired by succession or gift or rights in immovable property situated in the United States are in issue;"],[1,"(5) not otherwise encompassed in paragraph (2) above, in which money damages are sought against a foreign state for personal injury or death, or damage to or loss of property, occurring in the United States and caused by the tortious act or omission of that foreign state or of any official or employee of that foreign state while acting within the scope of his office or employment; except this paragraph shall not apply to—"],[2,"(A) any claim based upon the exercise or performance or the failure to exercise or perform a discretionary function regardless of whether the discretion be abused, or"],[2,"(B) any claim arising out of malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights; or"],[1,"(6) in which the action is brought, either to enforce an agreement made by the foreign state with or for the benefit of a private party to submit to arbitration all or any differences which have arisen or which may arise between the parties with respect to a defined legal relationship, whether contractual or not, concerning a subject matter capable of settlement by arbitration under the laws of the United States, or to confirm an award made pursuant to such an agreement to arbitrate, if (A) the arbitration takes place or is intended to take place in the United States, (B) the agreement or award is or may be governed by a treaty or other international agreement in force for the United States calling for the recognition and enforcement of arbitral awards, (C) the underlying claim, save for the agreement to arbitrate, could have been brought in a United States court under this section or section 1607, or (D) paragraph (1) of this subsection is otherwise applicable."],[0,"(b) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any case in which a suit in admiralty is brought to enforce a maritime lien against a vessel or cargo of the foreign state, which maritime lien is based upon a commercial activity of the foreign state: Provided, That—"],[1,"(1) notice of the suit is given by delivery of a copy of the summons and of the complaint to the person, or his agent, having possession of the vessel or cargo against which the maritime lien is asserted; and if the vessel or cargo is arrested pursuant to process obtained on behalf of the party bringing the suit, the service of process of arrest shall be deemed to constitute valid delivery of such notice, but the party bringing the suit shall be liable for any damages sustained by the foreign state as a result of the arrest if the party bringing the suit had actual or constructive knowledge that the vessel or cargo of a foreign state was involved; and"],[1,"(2) notice to the foreign state of the commencement of suit as provided in section 1608 of this title is initiated within ten days either of the delivery of notice as provided in paragraph (1) of this subsection or, in the case of a party who was unaware that the vessel or cargo of a foreign state was involved, of the date such party determined the existence of the foreign state's interest."],[0,"(c) Whenever notice is delivered under subsection (b)(1), the suit to enforce a maritime lien shall thereafter proceed and shall be heard and determined according to the principles of law and rules of practice of suits in rem whenever it appears that, had the vessel been privately owned and possessed, a suit in rem might have been maintained. A decree against the foreign state may include costs of the suit and, if the decree is for a money judgment, interest as ordered by the court, except that the court may not award judgment against the foreign state in an amount greater than the value of the vessel or cargo upon which the maritime lien arose. Such value shall be determined as of the time notice is served under subsection (b)(1). Decrees shall be subject to appeal and revision as provided in other cases of admiralty and maritime jurisdiction. Nothing shall preclude the plaintiff in any proper case from seeking relief in personam in the same action brought to enforce a maritime lien as provided in this section."],[0,"(d) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any action brought to foreclose a preferred mortgage, as defined in section 31301 of title 46. Such action shall be brought, heard, and determined in accordance with the provisions of chapter 313 of title 46 and in accordance with the principles of law and rules of practice of suits in rem, whenever it appears that had the vessel been privately owned and possessed a suit in rem might have been maintained."],[0,"[(e), (f) Repealed. Pub. L. 110–181, div. A, title X, §1083(b)(1)(B), Jan. 28, 2008, 122 Stat. 341.]"],[0,"(g) Limitation on Discovery.—"],[1,"(1) In general.—(A) Subject to paragraph (2), if an action is filed that would otherwise be barred by section 1604, but for section 1605A or section 1605B, the court, upon request of the Attorney General, shall stay any request, demand, or order for discovery on the United States that the Attorney General certifies would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action, until such time as the Attorney General advises the court that such request, demand, or order will no longer so interfere."],[1,"(B) A stay under this paragraph shall be in effect during the 12-month period beginning on the date on which the court issues the order to stay discovery. The court shall renew the order to stay discovery for additional 12-month periods upon motion by the United States if the Attorney General certifies that discovery would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action."],[1,"(2) Sunset.—(A) Subject to subparagraph (B), no stay shall be granted or continued in effect under paragraph (1) after the date that is 10 years after the date on which the incident that gave rise to the cause of action occurred."],[1,"(B) After the period referred to in subparagraph (A), the court, upon request of the Attorney General, may stay any request, demand, or order for discovery on the United States that the court finds a substantial likelihood would—"],[2,"(i) create a serious threat of death or serious bodily injury to any person;"],[2,"(ii) adversely affect the ability of the United States to work in cooperation with foreign and international law enforcement agencies in investigating violations of United States law; or"],[2,"(iii) obstruct the criminal case related to the incident that gave rise to the cause of action or undermine the potential for a conviction in such case."],[1,"(3) Evaluation of evidence.—The court's evaluation of any request for a stay under this subsection filed by the Attorney General shall be conducted ex parte and in camera."],[1,"(4) Bar on motions to dismiss.—A stay of discovery under this subsection shall constitute a bar to the granting of a motion to dismiss under rules 12(b)(6) and 56 of the Federal Rules of Civil Procedure."],[1,"(5) Construction.—Nothing in this subsection shall prevent the United States from seeking protective orders or asserting privileges ordinarily available to the United States."],[0,"(h) Jurisdictional Immunity for Certain Art Exhibition Activities.—"],[1,"(1) In general.—If—"],[2,"(A) a work is imported into the United States from any foreign state pursuant to an agreement that provides for the temporary exhibition or display of such work entered into between a foreign state that is the owner or custodian of such work and the United States or one or more cultural or educational institutions within the United States;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605?type=usc&year=mostrecent&link-type=html"},"op":10,"ar":1,"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","tname":"Judiciary and Judicial Procedure","by":{"0":"passim","1":"36, 42, 43, 5, 10, 42, 43, 46, passim, 43, 44, 34"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"0":"23"}},{"t":"usc","label":"45 U.S.C. § 51","url":"https://www.law.cornell.edu/uscode/text/45/51","by":{"0":"21"}},{"t":"law","label":"Pub. L. No. 80-772","by":{"0":"26"}},{"t":"law","label":"Foreign Sovereign Immunities Act, Pub. L. No. 94-583","url":"https://www.govinfo.gov/link/statute/90/2891","by":{"0":"passim"}},{"t":"reg","label":"31 C.F.R. pt. 501","url":"https://www.ecfr.gov/current/title-31/part-501","by":{"0":"42","2":"11"}},{"t":"rule","label":"Fed. R. Crim. P. 4.1","url":"https://www.law.cornell.edu/rules/frcrmp/rule_4.1","by":{"0":"37"}},{"t":"rule","label":"Fed. R. Crim. P. 32.2","url":"https://www.law.cornell.edu/rules/frcrmp/rule_32.2","by":{"0":"38"}},{"t":"case","label":"American Ins. Ass’n v. Garamendi","cite":"539 U.S. 396","y":2003,"id":"2002/02-722","sc":1,"op":1,"sum":"The Court held that California's HVIRA interferes with the president's ability to conduct the nation's foreign policy and is therefore preempted. The Court reasoned that an exercise of state power that concerns foreign relations must yield to the Federal Government's policy or that generally there is executive authority to decide what policy should be implemented.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"578 U.S. 212","y":2016,"id":"2015/14-770","sc":1,"sum":"The Court decided that a statute effectively directing a particular result in a single pending case does not violate the separation of powers.","sumSrc":"Oyez","by":{"1":"22, 30"}},{"t":"case","label":"Cassirer v. Thyssen-Bornemisza Collection Found.","cite":"142 S. Ct. 1502","y":2022,"id":"2021/20-1566","sc":1,"op":2,"sum":"In a suit raising non-federal claims against a foreign state or instrumentality under the Foreign Sovereign Immunities Act of 1976, a court should determine the substantive law by using the same choice-of-law rule applicable in a similar suit against a private party.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"9, 33, 35"}},{"t":"case","label":"Chicago & S. Air Lines, Inc. v. Waterman S.S. Corp.","cite":"333 U.S. 103","y":1948,"id":"scdb/1947-037","sc":1,"by":{"1":"31"}},{"t":"case","label":"Chisom v. Roemer","cite":"501 U.S. 380","y":1991,"id":"1990/90-757","sc":1,"sum":"The Court determined that if Congress had that aim, it would have indicated this exclusion explicitly. Consequently, the Court favored a broad interpretation of the word \"representative\" in section 2 of the Voting Rights Act, considering it to encompass all winners of popular elections.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Coale v. Société Coop. Suisse des Charbons","cite":"21 F.2d 180","y":1921,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.2d/21/180/","by":{"1":"18","2":"15"}},{"t":"case","label":"Cook Cnty. v. United States ex rel. Chandler","cite":"538 U.S. 119","y":2003,"id":"2002/01-1572","sc":1,"sum":"The Court held that the term \"person\" includes local governments. The Court noted that the County, as a recipient of federal funding, was clearly able to abuse federal spending and was thus subject to the FCA remedy that applied to prevent such abuse.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Devengoechea v. Bolivarian Republic of Venez.","cite":"889 F.3d 1213","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/889/1213/","by":{"1":"48"}},{"t":"case","label":"First Nat’l City Bank v. Banco Para El Comercio Exterior de Cuba","cite":"462 U.S. 611","y":1983,"id":"1982/81-984","sc":1,"sum":"Under principles of equity common to international law and federal common law, petitioner may apply the claimed setoff, notwithstanding the fact that respondent was established as a separate juridical entity.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 24","2":"12-13"}},{"t":"case","label":"Gould Coupler Co. v. U.S. Shipping Bd. Emergency Fleet Corp.","cite":"261 F. 716","y":1919,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./261/716/","by":{"1":"17","2":"15"}},{"t":"case","label":"Graham Cnty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"op":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Lockerty v. Phillips","cite":"319 U.S. 182","y":1943,"id":"scdb/1942-149","sc":1,"sum":"1. The Emergency Price Control Act of 1942 sets up a procedure whereby any person subject to any regulation or order promulgated under the Act may on \"protest\" of the regulation or order secure its review by the Administrator; and, if the protest is denied, the Act confers on the Emergency Court (and on the Supreme Court upon review of decisions of the Emergency Court) equity jurisdicLOCKERTY v. PHILLIPS. Counsel …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Merlini v. Canada","cite":"926 F.3d 21","y":2019,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/926/21/","by":{"1":"46"}},{"t":"case","label":"Molina v. Comision Reguladora del Mercado de Henequen","cite":"103 A. 397","y":1918,"court":"N.J.","url":"https://www.courtlistener.com/c/A./103/397/","by":{"1":"18","2":"15"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"1":"14, 36"}},{"t":"case","label":"Munaf v. Geren","cite":"553 U.S. 674","y":2008,"id":"2007/06-1666","sc":1,"sum":"Held that the habeas corpus statute extends to American citizens held overseas by American forces operating subject to an American chain of command even if part of a larger multinational force.","sumSrc":"Oyez","by":{"1":"22, 23, 30","2":"5"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"New York Cent. & Hudson River R.R. v. United States","cite":"212 U.S. 481","y":1909,"id":"scdb/1908-096","sc":1,"sum":"Congress can impute to a corporation the commission of certain criminal offenses and subject it to criminal prosecution therefor.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Pasquantino v. United States","cite":"544 U.S. 349","y":2005,"id":"2004/03-725","sc":1,"sum":"The Court held that the law's plain language criminalized the smuggling scheme in this case. The common-law revenue rule did not bar the prosecution of the scheme, because no common-law case as of 1952 clearly established that the rule barred the U.S. from prosecuting a fraudulent scheme to evade foreign taxes.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Petersen Energía Inversora S.A.U. v. Argentine Republic","cite":"895 F.3d 194","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/895/194/","by":{"1":"47"}},{"t":"case","label":"Republic of Iraq v. Beaty","cite":"556 U.S. 848","y":2009,"id":"2008/07-1090","sc":1,"by":{"1":"22, 37"}},{"t":"case","label":"Republic of Mex. v. Hoffman","cite":"324 U.S. 30","y":1945,"id":"scdb/1944-078","sc":1,"op":1,"sum":"1. The decisions of the two courts below that the vessel in question was not in the possession or service of the Mexican government are supported by the evidence.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"8, 15, 19, 20, 23","2":"12"}},{"t":"case","label":"Rodriguez v. Pan Am. Health Org.","cite":"29 F.4th 706","y":2022,"court":"D.C.Cir.","url":"https://www.courtlistener.com/c/F.4th/29/706/","sum":"Explaining that “a financial crime in the U.S.” involving “moving money” through U.S. bank accounts “constituted ‘commercial activity carried on in the United States’ ”.","sumSrc":"brief:1","by":{"1":"45, 48"}},{"t":"case","label":"SAS Inst. Inc. v. Iancu","cite":"138 S. Ct. 1348","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Salinas v. United States","cite":"522 U.S. 52","y":1997,"id":"1997/96-738","sc":1,"sum":"The Court held that section 666(a)(1)(B) does not require the Government to prove the bribe in question had a demonstrated effect upon federal funds.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Sloan Shipyards Corp. v. United States Shipping Bd. Emergency Fleet Corp.","cite":"258 U.S. 549","y":1922,"id":"scdb/1921-112","sc":1,"sum":"1. The Emergency Fleet Corporation, as originally created, had the powers of corporations under the laws of the District of Columbia, where it was incorporated, and was liable to be sued, there and elsewhere, upon its contracts and for its torts, notwithstanding the fact that it was a federal agency and that its stock was taken entirely by the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"7, 17","2":"15"}},{"t":"case","label":"United States v. Armstrong","cite":"517 U.S. 456","y":1996,"id":"1995/95-157","sc":1,"sum":"Announced by Chief Justice William H. Rehnquist, the Court held that in order to file selective-prosecution claims, defendants must show that the government failed to prosecute similarly situated suspects of other races. \"If the claim . . . were well founded,\" wrote Rehnquist, \"it should not have been an insuperable task to prove that persons of a different race were not prosecuted.\".","sumSrc":"Oyez","by":{"1":"31, 36"}},{"t":"case","label":"United States v. Batchelder","cite":"442 U.S. 114","y":1979,"id":"1978/78-776","sc":1,"sum":"A defendant convicted of violating § 922 (h) is properly sentenced under § 924 (a) even though his conduct also violates § 1202 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"10"}},{"t":"case","label":"United States v. Bowman","cite":"260 U.S. 94","y":1922,"id":"scdb/1922-015","sc":1,"sum":"1. A criminal statute dealing w-ith acts that are directly injurious to the Government and are capable of perpetration without regard to particular locality, and subjecting all who commit them to punishment, is to be construed as applicable to citizens of the United States upon the high seas or in a foreign country, though there be no express declaration to that effect.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"United States v. Deutsches Kalisyndikat Gesellschaft","cite":"31 F.2d 199","y":1929,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.2d/31/199/","by":{"1":"24, 25","2":"8"}},{"t":"case","label":"United States v. Fokker Servs. B.V.","cite":"818 F.3d 733","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/818/733/","by":{"1":"36"}},{"t":"case","label":"United States v. Ho","cite":"2016 WL 5875005","y":2016,"court":"E.D. Tenn. Oct. 7","by":{"1":"26"}},{"t":"case","label":"United States v. Noriega","cite":"117 F.3d 1206","y":1997,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/117/1206/","by":{"1":"23"}},{"t":"case","label":"United States v. Ravara","cite":"27 F. Cas. 714","y":1794,"court":"C.C.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Cas./27/714/","by":{"1":"24"}},{"t":"case","label":"United States v. Wilder","cite":"28 F. Cas. 601","y":1838,"court":"C.C.D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./28/601/","by":{"1":"19","2":"16"}},{"t":"case","label":"United States v. Williams","cite":"514 U.S. 527","y":1995,"id":"1994/94-395","sc":1,"sum":"Section 1346(a)(1) authorizes a refund suit by a party who, though not assessed a tax, paid the tax under protest to remove a federal tax lien from her property.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"1":"6"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"13"}},{"t":"usc","label":"28 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/28/1350","by":{"1":"40"}},{"t":"usc","label":"11 U.S.C. § 101et","url":"https://www.law.cornell.edu/uscode/text/11/101et","by":{"1":"13"}},{"t":"usc","label":"11 U.S.C. § 106","url":"https://www.law.cornell.edu/uscode/text/11/106","subs":["(a)"],"by":{"1":"13"}},{"t":"usc","label":"28 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/28/1330","subs":["(a)"],"stext":{"head":"§1330. Actions against foreign states","paras":[[0,"(a) The district courts shall have original jurisdiction without regard to amount in controversy of any nonjury civil action against a foreign state as defined in section 1603(a) of this title as to any claim for relief in personam with respect to which the foreign state is not entitled to immunity either under sections 1605–1607 of this title or under any applicable international agreement."],[0,"(b) Personal jurisdiction over a foreign state shall exist as to every claim for relief over which the district courts have jurisdiction under subsection (a) where service has been made under section 1608 of this title."],[0,"(c) For purposes of subsection (b), an appearance by a foreign state does not confer personal jurisdiction with respect to any claim for relief not arising out of any transaction or occurrence enumerated in sections 1605–1607 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1330?type=usc&year=mostrecent&link-type=html"},"op":8,"ar":5,"head":"§1330. Actions against foreign states","tname":"Judiciary and Judicial Procedure","by":{"1":"4, passim","2":"17-18, 20"}},{"t":"usc","label":"28 U.S.C. § 1603","url":"https://www.law.cornell.edu/uscode/text/28/1603","subs":["(b)(2)","(d)","(e)"],"by":{"1":"27, 46, 48, 10, 48"}},{"t":"usc","label":"28 U.S.C. § 1604","url":"https://www.law.cornell.edu/uscode/text/28/1604","stext":{"head":"§1604. Immunity of a foreign state from jurisdiction","paras":[[0,"Subject to existing international agreements to which the United States is a party at the time of enactment of this Act a foreign state shall be immune from the jurisdiction of the courts of the United States and of the States except as provided in sections 1605 to 1607 of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1604?type=usc&year=mostrecent&link-type=html"},"op":30,"ar":3,"head":"§1604. Immunity of a foreign state from jurisdiction","tname":"Judiciary and Judicial Procedure","by":{"1":"15, 35, 42"}},{"t":"usc","label":"28 U.S.C. § 1606","url":"https://www.law.cornell.edu/uscode/text/28/1606","stext":{"head":"§1606. Extent of liability","paras":[[0,"As to any claim for relief with respect to which a foreign state is not entitled to immunity under section 1605 or 1607 of this chapter, the foreign state shall be liable in the same manner and to the same extent as a private individual under like circumstances; but a foreign state except for an agency or instrumentality thereof shall not be liable for punitive damages; if, however, in any case wherein death was caused, the law of the place where the action or omission occurred provides, or has been construed to provide, for damages only punitive in nature, the foreign state shall be liable for actual or compensatory damages measured by the pecuniary injuries resulting from such death which were incurred by the persons for whose benefit the action was brought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1606?type=usc&year=mostrecent&link-type=html"},"op":1,"ar":1,"head":"§1606. Extent of liability","tname":"Judiciary and Judicial Procedure","by":{"1":"35"}},{"t":"usc","label":"28 U.S.C. § 1608","url":"https://www.law.cornell.edu/uscode/text/28/1608","subs":["(a)(1)","(d)"],"by":{"1":"9, 35, 35"}},{"t":"usc","label":"50 U.S.C. § 1701","url":"https://www.law.cornell.edu/uscode/text/50/1701","by":{"1":"2"}},{"t":"usc","label":"50 U.S.C. § 1705","url":"https://www.law.cornell.edu/uscode/text/50/1705","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","stext":{"head":"§2. Principals","paras":[[0,"(a) Whoever commits an offense against the United States or aids, abets, counsels, commands, induces or procures its commission, is punishable as a principal."],[0,"(b) Whoever willfully causes an act to be done which if directly performed by him or another would be an offense against the United States, is punishable as a principal."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§2. Principals","tname":"Crimes and Criminal Procedure","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/18/1344","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/18/1349","by":{"1":"2"}},{"t":"usc","label":"18 U.S.C. § 1956","url":"https://www.law.cornell.edu/uscode/text/18/1956","subs":["(a)(2)(A)","(h)"],"by":{"1":"2, 2"}},{"t":"usc","label":"18 U.S.C. § 3231","url":"https://www.law.cornell.edu/uscode/text/18/3231","stext":{"head":"§3231. District courts","paras":[[0,"The district courts of the United States shall have original jurisdiction, exclusive of the courts of the States, of all offenses against the laws of the United States."],[0,"Nothing in this title shall be held to take away or impair the jurisdiction of the courts of the several States under the laws thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3231?type=usc&year=mostrecent&link-type=html"},"op":24,"ar":1,"head":"§3231. District courts","tname":"Crimes and Criminal Procedure","by":{"1":"passim","2":"2-5, 7, 13, 18, 20"}},{"t":"usc","label":"28 U.S.C. § 1333","url":"https://www.law.cornell.edu/uscode/text/28/1333","stext":{"head":"§1333. Admiralty, maritime and prize cases","paras":[[0,"The district courts shall have original jurisdiction, exclusive of the courts of the States, of:"],[1,"(1) Any civil case of admiralty or maritime jurisdiction, saving to suitors in all cases all other remedies to which they are otherwise entitled."],[1,"(2) Any prize brought into the United States and all proceedings for the condemnation of property taken as prize."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1333?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1333. Admiralty, maritime and prize cases","tname":"Judiciary and Judicial Procedure","by":{"1":"40"}},{"t":"usc","label":"28 U.S.C. § 1391","url":"https://www.law.cornell.edu/uscode/text/28/1391","subs":["(f)"],"by":{"1":"9, 34"}},{"t":"usc","label":"28 U.S.C. § 1441","url":"https://www.law.cornell.edu/uscode/text/28/1441","subs":["(d)"],"by":{"1":"9, 35"}},{"t":"case","label":"Bank of the U.S. v. Planters’ Bank of Ga.","cite":"22 U.S. 904","y":1824,"id":"scdb/1824-035","sc":1,"sum":"The Bank of the United States v. The Planters’ Bank of Georgia.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"Fed. Land Bank of St. Louis v. Priddy","cite":"295 U.S. 229","y":1935,"id":"scdb/1934-121","sc":1,"op":1,"by":{"2":"12"}},{"t":"case","label":"Federal Republic of Germany v. Philipp","cite":"141 S. Ct. 703","y":2021,"id":"2020/19-351","sc":1,"sum":"The Foreign Sovereign Immunities Act’s expropriation exception, 28 U. S. C. §1605(a)(3), incorporates the domestic takings rule, which recognizes that a foreign sovereign’s taking of its own nationals’ property is not a violation of international law.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"10"}},{"t":"case","label":"FG Hemisphere Assocs. v. Democratic Republic of Congo","cite":"637 F.3d 373","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/637/373/","by":{"2":"11"}},{"t":"case","label":"FHA v. Burr","cite":"309 U.S. 242","y":1940,"id":"scdb/1939-089","sc":1,"sum":"1. Under the National Housing Act, as amended, which provides that the Administrator shall, in carrying out the provisions of certain of its titles, \"be authorized, in his official capacity, to sue and be sued in any court of competent jurisdiction, State or Federal,\" the Federal Housing Administration is subject to be garnished, under state law, for moneys due to an employee; but only those funds which have been …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Garcia v. San Antonio Metro. Transit Auth.","cite":"469 U.S. 528","y":1985,"id":"1983/82-1913","sc":1,"sum":"The Court ruled that Congress has the power under the Commerce Clause of the Constitution to extend the Fair Labor Standards Act to state and local governments.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Glass v. Sloop Betsey","cite":"3 U.S. 6","y":1794,"id":"scdb/1794-002","sc":1,"by":{"2":"6"}},{"t":"case","label":"Kiowa Tribe v. Mfg. Techs.","cite":"523 U.S. 751","y":1998,"id":"1997/96-1037","sc":1,"ar":1,"sum":"The Court held that Indian tribes enjoy sovereign immunity from civil suits on contracts, whether those contracts involve governmental or commercial activities and whether they were made on or off a reservation.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Lebron v. Nat’l R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"ar":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12, 15"}},{"t":"case","label":"Nathan v. Virginia","cite":"1 U.S. 77","y":1781,"court":"Pa. C.P.","url":"https://supreme.justia.com/cases/federal/us/1/77/","sc":1,"op":4,"by":{"2":"16"}},{"t":"case","label":"Republic of Argentina v. NML Cap.","cite":"573 U.S. Br. 134","y":2014,"url":"https://www.courtlistener.com/c/U.S.%20Br./573/134/","by":{"2":"10"}},{"t":"case","label":"SACE S.p.A. v. Republic of Paraguay","cite":"243 F. Supp. 3d 21","y":2017,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/243/21/","by":{"2":"23"}},{"t":"case","label":"Thacker v. TVA","cite":"139 S. Ct. 1435","y":2019,"id":"2018/17-1201","sc":1,"ar":1,"sum":"Title 16 U. S. C. §831c(b), which serves to waive the Tennessee Valley Authority’s sovereign immunity from suit, is not subject to a discretionary function exception of the kind in the Federal Tort Claims Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"12, 14"}},{"t":"case","label":"United States v. Greene","cite":"26 F. Cas. 33","y":1827,"court":"D. Me.","url":"https://www.courtlistener.com/c/F.%20Cas./26/33/","by":{"2":"4"}},{"t":"case","label":"United States v. Pangang Grp.","cite":"6 F.4th 946","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/946/","op":2,"ar":2,"by":{"2":"8"}},{"t":"case","label":"W.S. Kirkpatrick & Co. v. Env’t Tectonics Corp.","cite":"493 U.S. 400","y":1990,"id":"1989/87-2066","sc":1,"sum":"The Court held that state doctrine only applies when the case requires a US court to declare an act of a foreign sovereign nation invalid.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Will v. Mich. Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"sum":"Neither States nor state officials acting in their official capacities are \"persons\" within meaning of § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"Zivotofsky v. Kerry","cite":"576 U.S. 1","y":2015,"id":"2014/13-628","sc":1,"sum":"The Court held that a federal statute directing the Secretary of State to record the birthplace of a citizen born in Jerusalem as “Israel” if requested to do so impermissibly infringed on the President’s power to recognize foreign states.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"usc","label":"12 U.S.C. § 635","url":"https://www.law.cornell.edu/uscode/text/12/635","by":{"2":"13"}},{"t":"usc","label":"22 U.S.C. § 9612","url":"https://www.law.cornell.edu/uscode/text/22/9612","by":{"2":"13"}},{"t":"usc","label":"31 U.S.C. § 9101","url":"https://www.law.cornell.edu/uscode/text/31/9101","by":{"2":"13"}}]};